fn shift_char(c: String, k: Int) -> String {
  let letters = split("abcdefghijklmnopqrstuvwxyz", "")
  let upper_letters = split("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "")
  let hits = filter(enumerate(letters ++ upper_letters), |p| p.1 == c)
  return match first(hits) {
    Some(p) => {
      let base = if p.1 == c { letters } else { upper_letters }
      base |> drop(((p.0 + k) % 26 + 26) % 26) |> first() |> unwrap_or(c)
    },
    None => c,
  }
}

fn caesar_shift(s: String, k: Int) -> String {
  return s
    |> split("")
    |> map(|c| shift_char(c, k))
    |> join("")
}

