        if not digits:
            return {"ok": False, "error": f"missing number before {ch}"}
        rank, seconds = _UNITS[ch]
        if rank <= last_rank:
            return {"ok": False, "error": f"unit out of order: {ch}"}
        total += int(digits) * seconds
        last_rank = rank
        digits = ""
    if digits:
        return {"ok": False, "error": "missing unit"}
    return {"ok": True, "value": total}


