type EditOp =
  | { kind: "Insert"; text: string }
  | { kind: "Delete"; n: number }
  | { kind: "Left"; n: number }
  | { kind: "Right"; n: number }
  | { kind: "Undo" }
  | { kind: "Redo" };

export function text_editor(ops: EditOp[]): string {
  let text = "";
  let cur = 0;
  const history: [string, number][] = [];
  const redoHistory: [string, number][] = [];
  for (const op of ops) {
    switch (op.kind) {
      case "Insert":
        history.push([text, cur]);
        redoHistory.length = 0; // Clear redo history on insert
        text = text.slice(0, cur) + op.text + text.slice(cur);
        cur += op.text.length;
        break;
      case "Delete": {
        history.push([text, cur]);
        redoHistory.length = 0; // Clear redo history on delete
        const k = Math.min(op.n, cur);
        text = text.slice(0, cur - k) + text.slice(cur);
        cur -= k;
        break;
      }
      case "Left":
        cur = Math.max(0, cur - op.n);
        break;
      case "Right":
        cur = Math.min(text.length, cur + op.n);
        break;
      case "Undo": {
        const prev = history.pop();
        if (prev) {
          redoHistory.push([text, cur]);
          [text, cur] = prev;
        }
        break;
      }
      case "Redo": {
        const prev = redoHistory.pop();
        if (prev) {
          history.push([text, cur]);
          [text, cur] = prev;
        }
        break;
      }
    }
  }
  return text;
}

