    kind: Literal["Add"]

class Sub(TypedDict):
    kind: Literal["Sub"]

class Mul(TypedDict):
    kind: Literal["Mul"]

class Div(TypedDict):
    kind: Literal["Div"]

class Mod(TypedDict):
    kind: Literal["Mod"]

class Dup(TypedDict):
    kind: Literal["Dup"]

class Swap(TypedDict):
    kind: Literal["Swap"]

class Jz(TypedDict):
    kind: Literal["Jz"]
    target: int

