type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo
  | Redo

type Editor {
  text: String,
  cur: Int,
  history: List[(String, Int)],
  redo_history: List[(String, Int)],
}

fn step(e: Editor, op: EditOp) -> Editor {
  let cs = split(e.text, "")
  let saved = append(e.history, (e.text, e.cur))
  let redo_saved = append(e.redo_history, (e.text, e.cur))
  return match op {
    Insert(t) => insert(e, t, saved, redo_saved),
    Delete(n) => delete(e, min(n, e.cur), saved, redo_saved),
    Left(n) => Editor { text: e.text, cur: max(0, e.cur - n), history: e.history, redo_history: e.redo_history },
    Right(n) => Editor { text: e.text, cur: min(len(cs), e.cur + n), history: e.history, redo_history: e.redo_history },
    Undo => undo(e),
    Redo => redo(e),
  }
}

fn insert(e: Editor, t: String, saved: List[(String, Int)], redo_saved: List[(String, Int)]) -> Editor {
  let cs = split(e.text, "")
  let text = join(take(cs, e.cur), "") + t + join(drop(cs, e.cur), "")
  return Editor { text: text, cur: e.cur + str_len(t), history: saved, redo_history: [] }
}

fn delete(e: Editor, k: Int, saved: List[(String, Int)], redo_saved: List[(String, Int)]) -> Editor {
  let cs = split(e.text, "")
  let text = join(take(cs, e.cur - k), "") + join(drop(cs, e.cur), "")
  return Editor { text: text, cur: e.cur - k, history: saved, redo_history: [] }
}

fn undo(e: Editor) -> Editor {
  let n = len(e.history)
  return match last(e.history) {
    Some(p) => {
      let redo_saved = append(e.redo_history, (e.text, e.cur))
      Editor { text: p.0, cur: p.1, history: take(e.history, n - 1), redo_history: redo_saved }
    },
    None => e,
  }
}

fn redo(e: Editor) -> Editor {
  let n = len(e.redo_history)
  return match last(e.redo_history) {
    Some(p) => {
      let saved = append(e.history, (e.text, e.cur))
      Editor { text: p.0, cur: p.1, history: saved, redo_history: take(e.redo_history, n - 1) }
    },
    None => e,
  }
}

fn text_editor(ops: List[EditOp]) -> String {
  let start = Editor { text: "", cur: 0, history: [], redo_history: [] }
  return fold(ops, start, |e, op| step(e, op)).text
}

